"use client";
import { useEffect, useState, type FormEvent } from "react";
import { money, request, type Vendor } from "@/lib/api";
import { Heading, Notice, useDesk } from "@/components/desk";
export default function VendorsPage() {
  const { token, fail } = useDesk(); const [vendors, setVendors] = useState<Vendor[]>([]); const [error, setError] = useState(""); const [message, setMessage] = useState(""); const [pending, setPending] = useState(false); const [open, setOpen] = useState(false); const [loading, setLoading] = useState(true);
  async function load() { setVendors(await request<Vendor[]>(token, "/vendors")); setLoading(false); }
  useEffect(() => { void load().catch(e => { setError(fail(e)); setLoading(false); }); }, [token]); // eslint-disable-line react-hooks/exhaustive-deps
  async function add(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget); setPending(true); setError(""); setMessage("");
    try { await request(token, "/vendors", { method: "POST", body: JSON.stringify({ display_name: form.get("name"), expected_currency: form.get("currency") || null, baseline_amount_limit: form.get("limit") || null, is_approved: form.get("approved") === "on" }) }); await load(); setOpen(false); setMessage("Supplier registered. Revalidate the held invoice to apply the new policy, then approve its current revision."); }
    catch (e) { setError(fail(e)); } finally { setPending(false); }
  }
  return <><Heading eyebrow="SUPPLIER CONTROLS" title="Know your suppliers" subtitle="Explicit approvals and currency-specific limits, owned by your team."><button className="primary" disabled={pending} onClick={() => setOpen(!open)}>＋ Register supplier</button></Heading>{error && <Notice error>{error}</Notice>}{message && <Notice>{message}</Notice>}{open && <form className="panel vendor-form" onSubmit={add}><h2>Register a synthetic supplier</h2><div className="field-grid"><label>Supplier name<input name="name" required maxLength={200}/></label><label>Expected currency<select name="currency" defaultValue="USD"><option value="">No currency policy</option>{["USD", "EUR", "GBP", "JPY"].map(c => <option key={c}>{c}</option>)}</select></label><label>Amount limit (decimal string)<input name="limit" inputMode="decimal" placeholder="5000.00"/></label><label className="checkbox-label"><input type="checkbox" name="approved" defaultChecked/> Approved for invoice validation</label></div><p className="fine">Use the supplier name from the invoice. Amount limits require a currency. Approval never bypasses other invoice checks.</p><div className="action-row"><button className="primary" disabled={pending}>{pending ? "Registering…" : "Register supplier"}</button><button type="button" disabled={pending} onClick={() => setOpen(false)}>Cancel</button></div></form>}<section className="panel"><div className="panel-title"><h2>Supplier registry</h2><span className="muted">{vendors.length} suppliers</span></div><div className="table-scroll"><table><thead><tr><th>Supplier</th><th>Currency policy</th><th className="numeric">Amount limit</th><th>Approval</th></tr></thead><tbody>{vendors.map(row => <tr key={row.id}><td><strong>{row.display_name}</strong></td><td>{row.expected_currency || "No policy"}</td><td className="numeric amount">{money(row.baseline_amount_limit, row.expected_currency)}</td><td><span className={`badge ${row.is_approved ? "posted" : "needs_review"}`}>{row.is_approved ? "● Approved" : "● Unapproved"}</span></td></tr>)}</tbody></table>{loading ? <div className="empty">Loading suppliers…</div> : !vendors.length && <div className="empty">No suppliers registered yet.</div>}</div></section></>;
}
